#   CONFIGURABLE PARAMETERS — MODIFY HERE
# ============================================================

n_MC_samples = 10000     # Number of Monte Carlo samples
seed_MC      = 42        # RNG seed (None for non-reproducible)

# ============================================================
# EXECUTE PART 10
